import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Version 1.0.0.41 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.41-released.md","filePath":"change-log/release/version-1.0.0.41-released.md"}'),o={name:"change-log/release/version-1.0.0.41-released.md"};function r(l,e,s,d,c,g){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="version-1-0-0-41-released" tabindex="-1">Version 1.0.0.41 Released <a class="header-anchor" href="#version-1-0-0-41-released" aria-label="Permalink to &quot;Version 1.0.0.41 Released&quot;">​</a></h1><p><strong>Date: 24th Dec 2025</strong></p><p>Version <strong>1.0.0.41</strong> is an <strong>important infrastructure, real-time streaming, and stability release</strong>, focused on <strong>WebSocket connection pooling</strong>, <strong>options chain correctness</strong>, <strong>sandbox P&amp;L analytics</strong>, <strong>admin governance</strong>, and <strong>security hardening</strong>, along with an <strong>environment configuration update</strong> to support these enhancements.</p><p>This release builds on <strong>v1.0.0.40</strong> and improves <strong>scalability, observability, and operational control</strong>, especially for users handling <strong>large symbol subscriptions and multi-instance setups</strong>.</p><hr><h3 id="_0-upgrade-notice" tabindex="-1"><strong>0. Upgrade Notice</strong> <a class="header-anchor" href="#_0-upgrade-notice" aria-label="Permalink to &quot;**0. Upgrade Notice**&quot;">​</a></h3><p>This upgrade is <strong>not mandatory</strong>, but is <strong>strongly recommended</strong> for users who want to:</p><ul><li>Enable <strong>WebSocket connection pooling</strong></li><li>Stream large watchlists reliably</li><li>Use improved sandbox P&amp;L analytics</li><li>Access new admin-level market controls</li><li>Apply the latest security and stability fixes</li></ul><p>Upgrade guide:<br><a href="https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade</a></p><hr><h3 id="_1-market-data-quote-enhancements" tabindex="-1"><strong>1. Market Data &amp; Quote Enhancements</strong> <a class="header-anchor" href="#_1-market-data-quote-enhancements" aria-label="Permalink to &quot;**1. Market Data &amp; Quote Enhancements**&quot;">​</a></h3><h4 id="quote-fixes-improvements" tabindex="-1"><strong>Quote Fixes &amp; Improvements</strong> <a class="header-anchor" href="#quote-fixes-improvements" aria-label="Permalink to &quot;**Quote Fixes &amp; Improvements**&quot;">​</a></h4><ul><li><strong>Upstox</strong>: Previous close fixed in quote payloads</li><li><strong>Underlying indices</strong>: Previous close added for analytics</li><li><strong>Fyers WebSocket</strong>: <ul><li>Quote field structure updated</li><li>Improved consistency with REST quotes</li></ul></li></ul><h4 id="rate-limit-safety" tabindex="-1"><strong>Rate-Limit Safety</strong> <a class="header-anchor" href="#rate-limit-safety" aria-label="Permalink to &quot;**Rate-Limit Safety**&quot;">​</a></h4><ul><li><strong>Dhan Options Chain</strong>: <ul><li>Fixed field parameter mismatch</li><li>Added internal rate-limiting protection</li></ul></li></ul><hr><h3 id="_2-options-engine-derivatives" tabindex="-1"><strong>2. Options Engine &amp; Derivatives</strong> <a class="header-anchor" href="#_2-options-engine-derivatives" aria-label="Permalink to &quot;**2. Options Engine &amp; Derivatives**&quot;">​</a></h3><h4 id="options-chain-greeks" tabindex="-1"><strong>Options Chain &amp; Greeks</strong> <a class="header-anchor" href="#options-chain-greeks" aria-label="Permalink to &quot;**Options Chain &amp; Greeks**&quot;">​</a></h4><ul><li><strong>Samco</strong>: <ul><li>Options chain fixed</li><li>Greeks calculation stabilized</li><li>Index scrip mapping updated</li></ul></li><li><strong>Fyers</strong>: <ul><li>Bid / Ask values fixed in options chain</li></ul></li></ul><h4 id="expiry-handling" tabindex="-1"><strong>Expiry Handling</strong> <a class="header-anchor" href="#expiry-handling" aria-label="Permalink to &quot;**Expiry Handling**&quot;">​</a></h4><ul><li>Added expiry-aware Python sample code</li><li>Improved handling of expired contracts across APIs</li></ul><hr><h3 id="_3-websocket-real-time-infrastructure" tabindex="-1"><strong>3. WebSocket &amp; Real-Time Infrastructure</strong> <a class="header-anchor" href="#_3-websocket-real-time-infrastructure" aria-label="Permalink to &quot;**3. WebSocket &amp; Real-Time Infrastructure**&quot;">​</a></h3><h4 id="websocket-connection-pooling-new-–-optional" tabindex="-1"><strong>WebSocket Connection Pooling (New – Optional)</strong> <a class="header-anchor" href="#websocket-connection-pooling-new-–-optional" aria-label="Permalink to &quot;**WebSocket Connection Pooling (New – Optional)**&quot;">​</a></h4><ul><li>Introduced automatic WebSocket connection pooling</li><li>Supports broker symbol limits by spawning multiple connections</li><li>Prevents silent quote drops for large subscriptions</li><li>Configurable via <code>.env</code></li></ul><h4 id="pooling-stability-zmq-fixes" tabindex="-1"><strong>Pooling Stability &amp; ZMQ Fixes</strong> <a class="header-anchor" href="#pooling-stability-zmq-fixes" aria-label="Permalink to &quot;**Pooling Stability &amp; ZMQ Fixes**&quot;">​</a></h4><ul><li>Fixed ZMQ socket setup issues</li><li>Added connection test scripts and diagnostic logs</li><li>Introduced thread-local context detection to prevent: <ul><li>Duplicate publishers</li><li>Socket conflicts during pooled creation</li></ul></li></ul><h4 id="latency-improvements" tabindex="-1"><strong>Latency Improvements</strong> <a class="header-anchor" href="#latency-improvements" aria-label="Permalink to &quot;**Latency Improvements**&quot;">​</a></h4><ul><li>Telegram alerts moved off request thread</li><li>Reduced order placement latency</li></ul><hr><h3 id="_4-sandbox-p-amp-l-analytics" tabindex="-1"><strong>4. Sandbox, P&amp;L &amp; Analytics</strong> <a class="header-anchor" href="#_4-sandbox-p-amp-l-analytics" aria-label="Permalink to &quot;**4. Sandbox, P\\&amp;L &amp; Analytics**&quot;">​</a></h3><h4 id="sandbox-mode" tabindex="-1"><strong>Sandbox Mode</strong> <a class="header-anchor" href="#sandbox-mode" aria-label="Permalink to &quot;**Sandbox Mode**&quot;">​</a></h4><ul><li>Fixed day-wise P&amp;L tracking</li><li>Added P&amp;L history page</li><li>Improved historical continuity and accuracy</li></ul><h4 id="p-amp-l-tracker" tabindex="-1"><strong>P&amp;L Tracker</strong> <a class="header-anchor" href="#p-amp-l-tracker" aria-label="Permalink to &quot;**P\\&amp;L Tracker**&quot;">​</a></h4><ul><li>Added robust timestamp handling</li><li>Safely supports multiple broker timestamp formats</li></ul><hr><h3 id="_5-admin-governance-market-timings" tabindex="-1"><strong>5. Admin, Governance &amp; Market Timings</strong> <a class="header-anchor" href="#_5-admin-governance-market-timings" aria-label="Permalink to &quot;**5. Admin, Governance &amp; Market Timings**&quot;">​</a></h3><h4 id="admin-panel" tabindex="-1"><strong>Admin Panel</strong> <a class="header-anchor" href="#admin-panel" aria-label="Permalink to &quot;**Admin Panel**&quot;">​</a></h4><ul><li>New Admin Panel added for: <ul><li>Market timings</li><li>Exchange holidays</li><li>Freeze quantity management</li></ul></li></ul><h4 id="freeze-quantity-enforcement" tabindex="-1"><strong>Freeze Quantity Enforcement</strong> <a class="header-anchor" href="#freeze-quantity-enforcement" aria-label="Permalink to &quot;**Freeze Quantity Enforcement**&quot;">​</a></h4><ul><li>Freeze quantity stored in DB</li><li>Exposed via: <ul><li>Search API</li><li>Symbol API</li><li>Option Symbol API</li><li>Web UI search</li></ul></li><li>Prevents invalid order sizing at infra level</li></ul><hr><h3 id="_6-ui-dashboard-observability" tabindex="-1"><strong>6. UI, Dashboard &amp; Observability</strong> <a class="header-anchor" href="#_6-ui-dashboard-observability" aria-label="Permalink to &quot;**6. UI, Dashboard &amp; Observability**&quot;">​</a></h3><h4 id="ui-enhancements" tabindex="-1"><strong>UI Enhancements</strong> <a class="header-anchor" href="#ui-enhancements" aria-label="Permalink to &quot;**UI Enhancements**&quot;">​</a></h4><ul><li>Heatmap updated</li><li>Improved F&amp;O search in Web UI</li><li>Analyzer logs card text refined</li></ul><h4 id="logging-monitoring" tabindex="-1"><strong>Logging &amp; Monitoring</strong> <a class="header-anchor" href="#logging-monitoring" aria-label="Permalink to &quot;**Logging &amp; Monitoring**&quot;">​</a></h4><ul><li>Added centralized logging dashboard at <code>/logging</code></li><li>Improved structured logging across: <ul><li>WebSockets</li><li>Sandbox</li><li>Analyzer</li></ul></li><li>Reduced logging noise</li></ul><hr><h3 id="_7-sdk-configuration" tabindex="-1"><strong>7. SDK &amp; Configuration</strong> <a class="header-anchor" href="#_7-sdk-configuration" aria-label="Permalink to &quot;**7. SDK &amp; Configuration**&quot;">​</a></h3><h4 id="sdk" tabindex="-1"><strong>SDK</strong> <a class="header-anchor" href="#sdk" aria-label="Permalink to &quot;**SDK**&quot;">​</a></h4><ul><li>Tradeboard SDK version upgraded: <ul><li><code>1.0.44 → 1.0.45</code></li></ul></li></ul><h4 id="environment-configuration" tabindex="-1"><strong>Environment Configuration</strong> <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;**Environment Configuration**&quot;">​</a></h4><ul><li><code>.sample.env</code> updated to <strong>version 1.0.5</strong></li><li>New configuration options added to support: <ul><li>WebSocket pooling</li><li>Enhanced security</li><li>Improved logging and isolation</li></ul></li></ul><hr><h3 id="_8-security-stability" tabindex="-1"><strong>8. Security &amp; Stability</strong> <a class="header-anchor" href="#_8-security-stability" aria-label="Permalink to &quot;**8. Security &amp; Stability**&quot;">​</a></h3><ul><li>Fixed <strong>Marshmallow <code>Schema.load</code> DoS vulnerability</strong></li><li>Updated security documentation</li><li>Continued dependency and stability improvements</li></ul><hr><h3 id="summary" tabindex="-1"><strong>Summary</strong> <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;**Summary**&quot;">​</a></h3><p>Version <strong>1.0.0.41</strong> delivers:</p><ul><li>✅ Optional WebSocket connection pooling</li><li>✅ Improved real-time streaming stability</li><li>✅ Options chain fixes across brokers</li><li>✅ Sandbox P&amp;L history and accuracy improvements</li><li>✅ New admin controls for market governance</li><li>✅ Enhanced logging and observability</li><li>✅ SDK and configuration updates</li><li>✅ Security vulnerability fixes</li></ul><p>This release <strong>enhances scalability and operational safety</strong> while remaining <strong>backward-compatible</strong>, allowing users to opt-in to advanced real-time features as needed.</p><hr>',62)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
